import {afterEach,beforeEach,expect,it,vi} from 'vitest';import {mkdtempSync,readFileSync,readdirSync,rmSync,copyFileSync,mkdirSync,writeFileSync} from 'node:fs';import {join} from 'node:path';import {tmpdir} from 'node:os';import {pathToFileURL} from 'node:url';
let root:string,client:any;const body={eventId:'synthetic_compat_restore',hookType:'post_tool_use',sessionId:'synthetic',project:'synthetic',cwd:'/synthetic',timestamp:'2026-10-27T00:00:00Z',data:{tool_output:'original'}};
beforeEach(async()=>{root=mkdtempSync(join(tmpdir(),'am-compat-selected-'));const moduleDir=join(root,'client');mkdirSync(moduleDir);for(const file of ['_capture.mjs','long-session-hook-client.mjs'])writeFileSync(join(moduleDir,file),readFileSync(join(process.cwd(),'plugin/scripts/codex-compat',file),'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm,''));const {HookClient}=await import(pathToFileURL(join(moduleDir,'long-session-hook-client.mjs')).href);client=new HookClient({dir:join(root,'outbox'),url:'http://127.0.0.1:63000',secret:'synthetic'});vi.stubEnv('AGENTMEMORY_CAPTURE_DRAIN_CHILD','1');});
afterEach(()=>{vi.unstubAllGlobals();vi.unstubAllEnvs();rmSync(root,{recursive:true,force:true});});
async function accepted(){vi.stubGlobal('fetch',vi.fn(async()=>Response.json({eventId:body.eventId,status:'accepted',state:'sdk_completed',completed:true,completion:'sdk',durable:false},{status:201})));await client.enqueue('/agentmemory/observe',body);expect(await client.flush()).toBe(true);return readdirSync(join(root,'outbox','accepted-originals'))[0];}
it('posts exactly one selected original only to the explicit restore endpoint and retains the source',async()=>{
 const name=await accepted(),file=join(root,'outbox','accepted-originals',name),before=readFileSync(file,'utf8');const post=vi.fn(async(url:any,options:any)=>{expect(String(url)).toContain('/capture/restore-sdk');expect(JSON.parse(options.body)).toEqual({...body,captureCompletion:'sdk-v1'});return Response.json({eventId:body.eventId,status:'restored',completed:true,completion:'sdk',durable:false,sourceRestore:'sdk-v1'},{status:201});});vi.stubGlobal('fetch',post);
 expect(await client.restoreOriginal(name)).toEqual({completed:true,status:'restored'});expect(post).toHaveBeenCalledTimes(1);expect(readFileSync(file,'utf8')).toBe(before);
});
it('keeps source on old servers or uncertain delivery and never falls back to ordinary capture',async()=>{
 const name=await accepted(),file=join(root,'outbox','accepted-originals',name),before=readFileSync(file,'utf8');const post=vi.fn(async()=>new Response('{}',{status:404}));vi.stubGlobal('fetch',post);expect((await client.restoreOriginal(name)).completed).toBe(false);expect(post).toHaveBeenCalledTimes(1);expect(readFileSync(file,'utf8')).toBe(before);
 post.mockRejectedValueOnce(Error('synthetic network failure'));expect((await client.restoreOriginal(name)).completed).toBe(false);expect(post).toHaveBeenCalledTimes(2);expect(readFileSync(file,'utf8')).toBe(before);
});
it('rejects traversal and legacy files before any request',async()=>{
 const name=await accepted(),post=vi.fn();vi.stubGlobal('fetch',post);expect((await client.restoreOriginal('../'+name)).completed).toBe(false);writeFileSync(join(root,'outbox','accepted-originals','legacy.json'),JSON.stringify({path:'/agentmemory/observe',body}));expect((await client.restoreOriginal('legacy.json')).completed).toBe(false);expect(post).not.toHaveBeenCalled();
});
